/// <summary>
/// MPJ_28153 Interbranch Transfers	DCP 01/08/2022
/// </summary>
[ExtensionOf(tableStr(WMSPickingRoute))]
final class METWMSPickingRouteTable_Extension
{
}

Method.Source:
    /// <summary>
    /// Finishes multiple WMSPicking routes.
    /// </summary>
    /// <param name = "_packedList">A packed list of picking route ids, for routes that should be finished.</param>
    public static void finishMulti(container _packedList)
    {
        next finishMulti(_packedList); 

        WMSPickingRoute::METAdjustShipRemainMulti(_packedList);
    }

    /// <summary>
    /// Reduce the Ship Remain qty to match what was pickied
    /// </summary>
    /// <param name = "_metPackedList">A packed list of picking route ids</param>
    public static void METAdjustShipRemainMulti(container _metPackedList)
    {
        List                metPickingRouteIdList;
        ListEnumerator      metListEnumerator;
        WMSPickingRouteId   metPickingRouteId;

        if (!_metPackedList)
        {
            return;
        }

        metPickingRouteIdList = List::create(_metPackedList);

        if (!metPickingRouteIdList)
        {
            return;
        }
        
        metListEnumerator = metPickingRouteIdList.getEnumerator();

        while (metListEnumerator.moveNext())
        {
            metPickingRouteId = metListEnumerator.current();

            InventTransferLine::METAdjustShipRemain(metPickingRouteId);
        }
    }

    /// CB123 - SalesOrderExtractScreenforCSD
    /// <summary>
    /// Create wave post creation of sales order picking list journal
    /// </summary>
    public void insert()
    {
        next insert();

        if (this.transRefId)
        {
            SalesTable salesTable;

            select firstonly InventLocationId, InventSiteId, SalesId, METOrderExtractDateTime from  salesTable
                where salesTable.salesId == this.transRefId;

            if (SalesTable.salesid && DateTimeUtil::minValue() != salesTable.METOrderExtractDateTime)
            {
                this.createWave(salesTable);
            }
        }
        
    }

    /// CB123 - SalesOrderExtractScreenforCSD
    /// <summary>
    /// Create wave for the sales order
    /// </summary>
    /// <param name = "_salesTable">SalesTable buffer.</param>
    private void createWave(SalesTable _salesTable)
    {
        #OCCRetryCount

        try
        {
            if (_salesTable)
            {
                METWaveTable waveTable;
                boolean      waveLinesInserted = false;
                RecordInsertList waveLineInsertList = new RecordInsertList(tableNum(METWaveLine));

                try
                {
                    ttsbegin;

                    if (!METWaveTable::existByOrderExtractDateTime(_salesTable.METOrderExtractDateTime))
                    {
                        waveTable.clear();
                        waveTable.initValue();
                        waveTable.Warehouse      = _salesTable.InventLocationId;
                        waveTable.Site           = _salesTable.InventSiteId;
                        waveTable.generateWaveId(_salesTable.METOrderExtractDateTime);
                        waveTable.OrderExtractDateTime = _salesTable.METOrderExtractDateTime;
                        
                        if (waveTable.validateWrite())
                        {
                            waveTable.insert();
                        }
                    }
                    ttscommit;
                }
                catch (Exception::Deadlock)
                {
                    retry;
                }
                catch (Exception::DuplicateKeyException)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        throw Exception::UpdateConflictNotRecovered;
                    }
                    else
                    {
                        retry;
                    }
                }
                catch (Exception::UpdateConflict)
                {
                    if (appl.ttsLevel() == 0)
                    {
                        if (xSession::currentRetryCount() >= #RetryNum)
                        {
                            throw Exception::UpdateConflictNotRecovered;
                        }
                        else
                        {
                            retry;
                        }
                    }
                    else
                    {
                        throw Exception::UpdateConflict;
                    }
                }
                catch (Exception::Error)
                {
                    throw error("@SYS93835");
                }

                if (waveTable || METWaveTable::existByOrderExtractDateTime(_salesTable.METOrderExtractDateTime))
                {
                    METWaveLine      waveLine;
                    SalesLine        salesLine;
                    
                    if (!waveTable)
                    {
                        select firstonly OrderExtractDateTime, WaveId from waveTable
                            where waveTable.OrderExtractDateTime == _salesTable.METOrderExtractDateTime;
                    }

                    while select LineNum, SalesId, RecId from salesline
                        where salesLine.SalesId == _salesTable.SalesId
                    {
                        waveLine.clear();
                        waveLine.LineNumber     = salesLine.LineNum;
                        waveLine.DocumentNumber = salesLine.SalesId;
                        waveLine.WaveId         = waveTable.WaveId;
                        waveLine.Type           = METType::SalesOrder;
                        waveLine.DocNumRefRecId = salesLine.RecId;
                        waveLine.OrderExtractDateTime = waveTable.OrderExtractDateTime;

                        if (waveLine.validateWrite())
                        {
                            waveLineInsertList.add(waveLine);
                            waveLinesInserted = true;
                        }
                    }
                }

                if (waveLinesInserted)
                {
                    ttsbegin;
                    waveLineInsertList.insertDatabase();
                    ttscommit;
                }
                
            }
        }
        catch
        {
            error ("@WAX:UpdateCancelled");
        }
    }
